1	#include "rbtree.h"
2	#include <stdio.h>
3	#include <stdbool.h>
4	#include <stdlib.h>
5	#include <string.h>
6	
7	typedef enum { RED, BLACK } rb_color_t;
8	
9	struct rb_node {
10	    char           *key;
11	    void           *value;
12	    struct rb_node *parent;
13	    struct rb_node *left;
14	    struct rb_node *right;
15	    rb_color_t      color;
16	};
17	
18	struct rbtree {
19	    struct rb_node   *root;
20	    size_t            size;
21	    rb_value_free_fn  value_free;
22	};
23	
24	static void *rb_malloc(size_t n) { return malloc(n); }
25	static void  rb_free(void *p)    { free(p); }
26	
27	static bool is_red(const struct rb_node *n)  { return n != NULL && n->color == RED; }
28	static bool is_black(const struct rb_node *n) { return !is_red(n); }
29	
30	rbtree_t *rb_create(rb_value_free_fn value_free) {
31	    rbtree_t *t = rb_malloc(sizeof *t);
32	    if (t == NULL) return NULL;
33	    t->root = NULL;
34	    t->size = 0;
35	    t->value_free = value_free;
36	    return t;
37	}
38	
39	void *rb_find(const rbtree_t *t, const char *key) {
40	    struct rb_node *cur = t->root;
41	    while (cur != NULL) {
42	        int cmp = strcmp(key, cur->key);
43	        if (cmp == 0) return cur->value;
44	        cur = (cmp < 0) ? cur->left : cur->right;
45	    }
46	    return NULL;
47	}
48	
49	/* Standard BST rotation, extended to keep parent pointers and t->root
50	 * correct — rotations own root maintenance, not rb_validate. */
51	static void rotate_left(rbtree_t *t, struct rb_node *x) {
52	    struct rb_node *y = x->right;
53	    x->right = y->left;
54	    if (y->left != NULL) y->left->parent = x;
55	    y->parent = x->parent;
56	    if (x->parent == NULL)        t->root = y;
57	    else if (x == x->parent->left) x->parent->left = y;
58	    else                            x->parent->right = y;
59	    y->left = x;
60	    x->parent = y;
61	}
62	
63	static void rotate_right(rbtree_t *t, struct rb_node *x) {
64	    struct rb_node *y = x->left;
65	    x->left = y->right;
66	    if (y->right != NULL) y->right->parent = x;
67	    y->parent = x->parent;
68	    if (x->parent == NULL)         t->root = y;
69	    else if (x == x->parent->right) x->parent->right = y;
70	    else                             x->parent->left = y;
71	    y->right = x;
72	    x->parent = y;
73	}
74	
75	static void insert_fixup(rbtree_t *t, struct rb_node *z) {
76	    /* Invariant: z is red. Loop while z's parent is also red (the only
77	     * possible violation after a plain BST insert of a red node). */
78	    while (is_red(z->parent)) {
79	        struct rb_node *parent = z->parent;
80	        struct rb_node *grandparent = parent->parent;
81	        if (parent == grandparent->left) {
82	            struct rb_node *uncle = grandparent->right;
83	            if (is_red(uncle)) {
84	                parent->color = BLACK;
85	                uncle->color = BLACK;
86	                grandparent->color = RED;
87	                z = grandparent;
88	            } else {
89	                if (z == parent->right) {
90	                    z = parent;
91	                    rotate_left(t, z);
92	                    parent = z->parent;
93	                }
94	                parent->color = BLACK;
95	                grandparent->color = RED;
96	                rotate_right(t, grandparent);
97	            }
98	        } else {
99	            struct rb_node *uncle = grandparent->left;
100	            if (is_red(uncle)) {
101	                parent->color = BLACK;
102	                uncle->color = BLACK;
103	                grandparent->color = RED;
104	                z = grandparent;
105	            } else {
106	                if (z == parent->left) {
107	                    z = parent;
108	                    rotate_right(t, z);
109	                    parent = z->parent;
110	                }
111	                parent->color = BLACK;
112	                grandparent->color = RED;
113	                rotate_left(t, grandparent);
114	            }
115	        }
116	    }
117	    t->root->color = BLACK;
118	}
119	
120	int rb_insert(rbtree_t *t, const char *key, void *value) {
121	    struct rb_node *parent = NULL;
122	    struct rb_node *cur = t->root;
123	    int cmp = 0;
124	    while (cur != NULL) {
125	        cmp = strcmp(key, cur->key);
126	        if (cmp == 0) {
127	            if (t->value_free) t->value_free(cur->value);
128	            cur->value = value;
129	            return 0;
130	        }
131	        parent = cur;
132	        cur = (cmp < 0) ? cur->left : cur->right;
133	    }
134	
135	    struct rb_node *n = rb_malloc(sizeof *n);
136	    if (n == NULL) return -1;
137	
138	    size_t keylen = strlen(key) + 1;
139	    n->key = rb_malloc(keylen);
140	    if (n->key == NULL) {
141	        rb_free(n);
142	        return -1;
143	    }
144	    memcpy(n->key, key, keylen);
145	
146	    n->value = value;
147	    n->color = RED;
148	    n->left = n->right = NULL;
149	    n->parent = parent;
150	
151	    if (parent == NULL)      t->root = n;
152	    else if (cmp < 0)        parent->left = n;
153	    else                     parent->right = n;
154	
155	    insert_fixup(t, n);
156	    t->size++;
157	    return 0;
158	}
159	
160	static struct rb_node *find_node(const rbtree_t *t, const char *key) {
161	    struct rb_node *cur = t->root;
162	    while (cur != NULL) {
163	        int cmp = strcmp(key, cur->key);
164	        if (cmp == 0) return cur;
165	        cur = (cmp < 0) ? cur->left : cur->right;
166	    }
167	    return NULL;
168	}
169	
170	static struct rb_node *tree_min(struct rb_node *n) {
171	    while (n->left != NULL) n = n->left;
172	    return n;
173	}
174	
175	/* Puts v in u's slot (u->parent, or t->root) -- the only place delete
176	 * touches t->root or reparents a node, mirroring the rotations. */
177	static void transplant(rbtree_t *t, struct rb_node *u, struct rb_node *v) {
178	    if (v != NULL) v->parent = u->parent;
179	    if (u->parent == NULL)         t->root = v;
180	    else if (u == u->parent->left) u->parent->left = v;
181	    else                            u->parent->right = v;
182	}
183	
184	/* x may be NULL (NIL); since NULL can't carry its own parent pointer,
185	 * (parent, x) is threaded through the loop as an explicit pair instead
186	 * of ever reading x->parent -- see NOTES.md's devlog on why this tree
187	 * has no shared sentinel. */
188	static void delete_fixup(rbtree_t *t, struct rb_node *parent, struct rb_node *x) {
189	    while (parent != NULL && is_black(x)) {
190	        if (x == parent->left) {
191	            struct rb_node *sib = parent->right;
192	            if (is_red(sib)) {                     /* Case 5: sibling red */
193	                sib->color = BLACK;
194	                parent->color = RED;
195	                rotate_left(t, parent);
196	                sib = parent->right;
197	            }
198	            if (is_black(sib->left) && is_black(sib->right)) { /* Case 3: both nephews black */
199	                sib->color = RED;
200	                x = parent;
201	                parent = x->parent;
202	            } else {
203	                if (is_black(sib->right)) {         /* near red / far black: convert first */
204	                    if (sib->left != NULL) sib->left->color = BLACK;
205	                    sib->color = RED;
206	                    rotate_right(t, sib);
207	                    sib = parent->right;
208	                }
209	                sib->color = parent->color;         /* Case 4: far nephew red, terminal */
210	                parent->color = BLACK;
211	                if (sib->right != NULL) sib->right->color = BLACK;
212	                rotate_left(t, parent);
213	                return;
214	            }
215	        } else {
216	            /* exact mirror: left/right swapped, rotate_right/rotate_left swapped */
217	            struct rb_node *sib = parent->left;
218	            if (is_red(sib)) {
219	                sib->color = BLACK;
220	                parent->color = RED;
221	                rotate_right(t, parent);
222	                sib = parent->left;
223	            }
224	            if (is_black(sib->left) && is_black(sib->right)) {
225	                sib->color = RED;
226	                x = parent;
227	                parent = x->parent;
228	            } else {
229	                if (is_black(sib->left)) {
230	                    if (sib->right != NULL) sib->right->color = BLACK;
231	                    sib->color = RED;
232	                    rotate_left(t, sib);
233	                    sib = parent->left;
234	                }
235	                sib->color = parent->color;
236	                parent->color = BLACK;
237	                if (sib->left != NULL) sib->left->color = BLACK;
238	                rotate_right(t, parent);
239	                return;
240	            }
241	        }
242	    }
243	    if (x != NULL) x->color = BLACK;
244	}
245	
246	int rb_delete(rbtree_t *t, const char *key) {
247	    struct rb_node *z = find_node(t, key);
248	    if (z == NULL) return -1;
249	
250	    struct rb_node *n;
251	    bool free_own_payload = true;
252	
253	    if (z->left != NULL && z->right != NULL) {
254	        struct rb_node *y = tree_min(z->right);
255	        rb_free(z->key);
256	        if (t->value_free) t->value_free(z->value);
257	        z->key = y->key;
258	        z->value = y->value;
259	        n = y;
260	        free_own_payload = false;
261	    } else {
262	        n = z;
263	    }
264	
265	    struct rb_node *child = (n->left != NULL) ? n->left : n->right;
266	    bool n_was_black = is_black(n);
267	    transplant(t, n, child);
268	
269	    if (n_was_black) {
270	        if (child != NULL) {
271	            child->color = BLACK;             /* STEP1: absorbs the debt locally */
272	        } else {
273	            delete_fixup(t, n->parent, NULL); /* STEP2: only after transplant has run */
274	        }
275	    }
276	
277	    if (free_own_payload) {
278	        rb_free(n->key);
279	        if (t->value_free) t->value_free(n->value);
280	    }
281	    rb_free(n);
282	    t->size--;
283	    return 0;
284	}
285	
286	size_t rb_size(const rbtree_t *t) {
287	    return t->size;
288	}
289	
290	static void foreach_inorder(const struct rb_node *n,
291	                             void (*fn)(const char *, void *, void *), void *ctx) {
292	    if (n == NULL) return;
293	    foreach_inorder(n->left, fn, ctx);
294	    fn(n->key, n->value, ctx);
295	    foreach_inorder(n->right, fn, ctx);
296	}
297	
298	void rb_foreach(const rbtree_t *t,
299	                void (*fn)(const char *key, void *value, void *ctx), void *ctx) {
300	    foreach_inorder(t->root, fn, ctx);
301	}
302	
303	struct validate_state {
304	    const char *prev_key;
305	    bool        order_ok;
306	    size_t      count;
307	};
308	
309	static void validate_walk(const struct rb_node *n, struct validate_state *st) {
310	    if (n == NULL) return;
311	    validate_walk(n->left, st);
312	    if (st->prev_key != NULL && strcmp(st->prev_key, n->key) >= 0) {
313	        st->order_ok = false;
314	    }
315	    st->prev_key = n->key;
316	    st->count++;
317	    validate_walk(n->right, st);
318	}
319	
320	static bool has_red_red(const struct rb_node *n) {
321	    if (n == NULL) return false;
322	    if (is_red(n) && (is_red(n->left) || is_red(n->right))) return true;
323	    return has_red_red(n->left) || has_red_red(n->right);
324	}
325	
326	/* Returns the subtree's black-height, or -1 if any root-to-NIL path within it
327	 * has already been found to disagree with another. NULL (NIL) contributes a
328	 * black-height of 1 by convention; a black node adds 1 on top of its children's
329	 * (equal) black-height. */
330	static int black_height(const struct rb_node *n) {
331	    if (n == NULL) return 1;
332	    int lh = black_height(n->left);
333	    if (lh == -1) return -1;
334	    int rh = black_height(n->right);
335	    if (rh == -1) return -1;
336	    if (lh != rh) return -1;
337	    return lh + (is_black(n) ? 1 : 0);
338	}
339	
340	int rb_validate(const rbtree_t *t) {
341	    if (is_red(t->root)) {
342	        fprintf(stderr, "rb_validate: invariant 1 violated (root is red)\n");
343	        return 1;
344	    }
345	    if (has_red_red(t->root)) {
346	        fprintf(stderr, "rb_validate: invariant 2 violated "
347	                         "(a red node has a red child)\n");
348	        return 2;
349	    }
350	    if (black_height(t->root) == -1) {
351	        fprintf(stderr, "rb_validate: invariant 3 violated "
352	                         "(root-to-NIL paths have differing black-height)\n");
353	        return 3;
354	    }
355	
356	    struct validate_state st = { .prev_key = NULL, .order_ok = true, .count = 0 };
357	    validate_walk(t->root, &st);
358	
359	    if (!st.order_ok) {
360	        fprintf(stderr, "rb_validate: invariant 4 violated "
361	                         "(in-order keys not strictly increasing under strcmp)\n");
362	        return 4;
363	    }
364	    if (st.count != t->size) {
365	        fprintf(stderr, "rb_validate: invariant 5 violated "
366	                         "(rb_size=%zu, actual node count=%zu)\n", t->size, st.count);
367	        return 5;
368	    }
369	    return 0;
370	}
371	
372	void rb_destroy(rbtree_t *t) {
373	    if (t == NULL) return;
374	    struct rb_node *cur = t->root;
375	    while (cur != NULL) {
376	        struct rb_node *next;
377	        if (cur->left == NULL) {
378	            next = cur->right;
379	            rb_free(cur->key);
380	            if (t->value_free) t->value_free(cur->value);
381	            rb_free(cur);
382	        } else {
383	            struct rb_node *left = cur->left;
384	            cur->left = left->right;
385	            left->right = cur;
386	            next = left; /* re-enter the loop rooted at the promoted node */
387	        }
388	        cur = next;
389	    }
390	    rb_free(t);
391	}
392	
393	#ifdef RBTREE_TEST_HOOKS
394	/* Test-only hooks for exercising rb_validate's negative paths (invariants
395	 * 1-5). Compiled in only when RBTREE_TEST_HOOKS is defined (test_rbtree's
396	 * build only, per the Makefile) so production/grading builds that compile
397	 * this file without the macro never see these symbols at all. Each hook
398	 * mutates only existing struct fields on nodes the tree already owns --
399	 * no allocation, no freeing -- so rb_destroy's pointer-only teardown walk
400	 * (left/right only; it never reads color, key contents, or t->size) stays
401	 * safe to call afterward regardless of which invariant was broken.
402	 *
403	 * rb_validate checks invariants in order (1: root black, 2: no red-red,
404	 * 3: black-height, 4: ordering, 5: size) and returns on the first failure,
405	 * which is what lets each hook below isolate its target invariant's return
406	 * code even when a mutation has a side effect on a later check. */
407	
408	/* Invariant 1: flip the root red. Root-color is checked first and
409	 * unconditionally, so this isolates invariant 1 regardless of anything
410	 * else about the tree. */
411	void rb_test_force_root_red(rbtree_t *t) {
412	    if (t != NULL && t->root != NULL) t->root->color = RED;
413	}
414	
415	/* Invariant 2: find a RED node with a real (non-NULL) BLACK child and flip
416	 * that child RED, producing a red-red pair. Returns 1 if found and
417	 * corrupted, 0 if the fixture didn't have the needed shape. */
418	static struct rb_node *find_red_with_black_child(struct rb_node *n) {
419	    if (n == NULL) return NULL;
420	    if (n->color == RED &&
421	        ((n->left != NULL && n->left->color == BLACK) ||
422	         (n->right != NULL && n->right->color == BLACK))) {
423	        return n;
424	    }
425	    struct rb_node *found = find_red_with_black_child(n->left);
426	    if (found != NULL) return found;
427	    return find_red_with_black_child(n->right);
428	}
429	
430	int rb_test_force_red_red(rbtree_t *t) {
431	    if (t == NULL) return 0;
432	    struct rb_node *p = find_red_with_black_child(t->root);
433	    if (p == NULL) return 0;
434	    struct rb_node *child = (p->left != NULL && p->left->color == BLACK)
435	                             ? p->left : p->right;
436	    child->color = RED;
437	    return 1;
438	}
439	
440	/* Invariant 3: find a non-root BLACK node whose parent is BLACK and whose
441	 * own children are both BLACK-or-NIL, then flip it RED. That perturbs only
442	 * that node's subtree's black count -- it can't create a red-red pair
443	 * (parent stays black, its own children stay black) and it doesn't touch
444	 * the root, so it isolates invariant 3 rather than tripping 1 or 2 first.
445	 * Returns 1 if found and corrupted, 0 otherwise. */
446	static struct rb_node *find_isolated_black_flip_target(struct rb_node *n) {
447	    if (n == NULL) return NULL;
448	    if (n->parent != NULL && n->color == BLACK && is_black(n->parent) &&
449	        is_black(n->left) && is_black(n->right)) {
450	        return n;
451	    }
452	    struct rb_node *found = find_isolated_black_flip_target(n->left);
453	    if (found != NULL) return found;
454	    return find_isolated_black_flip_target(n->right);
455	}
456	
457	int rb_test_break_black_height(rbtree_t *t) {
458	    if (t == NULL) return 0;
459	    struct rb_node *n = find_isolated_black_flip_target(t->root);
460	    if (n == NULL) return 0;
461	    n->color = RED;
462	    return 1;
463	}
464	
465	/* Invariant 4: swap the key pointers of two existing nodes (located by
466	 * their current key values), which breaks in-order strictly-increasing
467	 * order without touching allocation, color, or structure -- each string is
468	 * still owned by exactly one node afterward, just a different one. Returns
469	 * 1 if both keys were found and swapped, 0 otherwise. */
470	static struct rb_node *find_by_key(struct rb_node *n, const char *key) {
471	    while (n != NULL) {
472	        int cmp = strcmp(key, n->key);
473	        if (cmp == 0) return n;
474	        n = (cmp < 0) ? n->left : n->right;
475	    }
476	    return NULL;
477	}
478	
479	int rb_test_swap_keys(rbtree_t *t, const char *key1, const char *key2) {
480	    if (t == NULL) return 0;
481	    struct rb_node *n1 = find_by_key(t->root, key1);
482	    struct rb_node *n2 = find_by_key(t->root, key2);
483	    if (n1 == NULL || n2 == NULL || n1 == n2) return 0;
484	    char *tmp = n1->key;
485	    n1->key = n2->key;
486	    n2->key = tmp;
487	    return 1;
488	}
489	
490	/* Invariant 5: directly desync the size counter from the real node count,
491	 * touching nothing else. Works on any tree, even empty. */
492	void rb_test_bump_size(rbtree_t *t) {
493	    if (t != NULL) t->size += 1;
494	}
495	#endif
